//! Shared helpers for the `hoard-gguf` integration tests.
//!
//! The committed fixtures under `tests/fixtures/` are generated by
//! `tests/generate.rs`. The [`RawGguf`] builder here can assemble small
//! synthetic files (including deliberately malformed ones) without enabling
//! the crate's `testing` feature, so the malformed-file tests run in every
//! feature configuration.

#![allow(dead_code)]

use std::path::PathBuf;

/// Directory of the crate's committed synthetic fixtures.
pub fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

/// Directory of the crate's committed golden JSON documents.
pub fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/golden")
}

/// Absolute path of a file in the repository's `fixtures/real/` directory.
pub fn real_fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/real")
        .join(name)
}

/// Read a committed synthetic fixture, with a pointer to the regeneration
/// command when it is missing.
pub fn read_fixture(name: &str) -> Vec<u8> {
    let path = fixtures_dir().join(name);
    std::fs::read(&path).unwrap_or_else(|error| {
        panic!(
            "cannot read fixture {}: {error}\n\
             run `UPDATE_FIXTURES=1 cargo test -p hoard-gguf --features testing --test generate`",
            path.display()
        )
    })
}

/// Bytes of `tests/fixtures/synthetic-minimal.gguf`.
pub fn minimal_gguf() -> Vec<u8> {
    read_fixture("synthetic-minimal.gguf")
}

/// Bytes of `tests/fixtures/synthetic-rich.gguf`.
pub fn rich_gguf() -> Vec<u8> {
    read_fixture("synthetic-rich.gguf")
}

/// Little-endian byte writer used by the raw GGUF builder below.
#[derive(Debug, Default, Clone)]
pub struct Writer {
    /// Bytes written so far.
    pub bytes: Vec<u8>,
}

impl Writer {
    /// Create an empty writer.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Append raw bytes.
    pub fn raw(&mut self, bytes: &[u8]) -> &mut Self {
        self.bytes.extend_from_slice(bytes);
        self
    }

    /// Append one byte.
    pub fn u8(&mut self, value: u8) -> &mut Self {
        self.bytes.push(value);
        self
    }

    /// Append a little-endian `u16`.
    pub fn u16(&mut self, value: u16) -> &mut Self {
        self.bytes.extend_from_slice(&value.to_le_bytes());
        self
    }

    /// Append a little-endian `u32`.
    pub fn u32(&mut self, value: u32) -> &mut Self {
        self.bytes.extend_from_slice(&value.to_le_bytes());
        self
    }

    /// Append a little-endian `i32`.
    pub fn i32(&mut self, value: i32) -> &mut Self {
        self.bytes.extend_from_slice(&value.to_le_bytes());
        self
    }

    /// Append a little-endian `f32`.
    pub fn f32(&mut self, value: f32) -> &mut Self {
        self.bytes.extend_from_slice(&value.to_le_bytes());
        self
    }

    /// Append a little-endian `u64`.
    pub fn u64(&mut self, value: u64) -> &mut Self {
        self.bytes.extend_from_slice(&value.to_le_bytes());
        self
    }

    /// Append a GGUF string (length prefix plus UTF-8 bytes).
    pub fn string(&mut self, value: &str) -> &mut Self {
        self.u64(value.len() as u64).raw(value.as_bytes())
    }

    /// Append `count` zero bytes.
    pub fn zeros(&mut self, count: usize) -> &mut Self {
        self.bytes.resize(self.bytes.len() + count, 0);
        self
    }

    /// Grow to a multiple of `alignment` by appending zero bytes.
    pub fn pad_to_alignment(&mut self, alignment: usize) -> &mut Self {
        let remainder = self.bytes.len() % alignment;
        if remainder != 0 {
            self.zeros(alignment - remainder);
        }
        self
    }

    /// Consume the writer and return the bytes.
    #[must_use]
    pub fn into_bytes(self) -> Vec<u8> {
        self.bytes
    }
}

/// Encode a GGUF string payload (used inside metadata values and arrays).
#[must_use]
pub fn string_payload(value: &str) -> Vec<u8> {
    let mut writer = Writer::new();
    writer.string(value);
    writer.into_bytes()
}

/// Encode an array metadata payload: element type, count, then encoded
/// elements.
#[must_use]
pub fn array_payload(element_type_id: u32, elements: &[Vec<u8>]) -> Vec<u8> {
    let mut writer = Writer::new();
    writer.u32(element_type_id).u64(elements.len() as u64);
    for element in elements {
        writer.raw(element);
    }
    writer.into_bytes()
}

/// Append the 24-byte GGUF header.
pub fn header(writer: &mut Writer, version: u32, tensor_count: u64, metadata_count: u64) {
    writer
        .raw(b"GGUF")
        .u32(version)
        .u64(tensor_count)
        .u64(metadata_count);
}

/// Append a metadata entry with a raw payload.
pub fn metadata_entry(writer: &mut Writer, key: &str, type_id: u32, payload: &[u8]) {
    writer.string(key).u32(type_id).raw(payload);
}

/// Append a metadata entry whose key bytes are given raw (for invalid UTF-8
/// keys).
pub fn metadata_entry_raw_key(writer: &mut Writer, key: &[u8], type_id: u32, payload: &[u8]) {
    writer
        .u64(key.len() as u64)
        .raw(key)
        .u32(type_id)
        .raw(payload);
}

/// Append a tensor info with the given relative offset.
pub fn tensor_info(writer: &mut Writer, name: &str, dims: &[u64], type_id: u32, offset: u64) {
    writer.string(name).u32(dims.len() as u32);
    for dim in dims {
        writer.u64(*dim);
    }
    writer.u32(type_id).u64(offset);
}

/// A raw GGUF assembler for tests.
///
/// Metadata entries and tensor infos are written in insertion order; the data
/// section is zero-filled to the requested length after alignment padding, and
/// any trailing bytes are appended last.
#[derive(Debug, Clone)]
pub struct RawGguf {
    /// Version word.
    pub version: u32,
    /// Magic bytes.
    pub magic: [u8; 4],
    /// `(key, type_id, payload)` metadata entries.
    pub metadata: Vec<(Vec<u8>, u32, Vec<u8>)>,
    /// `(name, dims, type_id, offset)` tensor infos.
    pub tensors: Vec<(String, Vec<u64>, u32, u64)>,
    /// Alignment used for the data section start (not written to metadata).
    pub alignment: u32,
    /// Length of the zero-filled tensor data section.
    pub data_len: usize,
    /// Override the tensor count in the header.
    pub declared_tensor_count: Option<u64>,
    /// Override the metadata count in the header.
    pub declared_metadata_count: Option<u64>,
    /// Bytes appended after the data section.
    pub trailing: Vec<u8>,
}

impl Default for RawGguf {
    fn default() -> Self {
        Self::new()
    }
}

impl RawGguf {
    /// Start a version 3 GGUF with no metadata, no tensors, and 32-byte
    /// alignment.
    #[must_use]
    pub fn new() -> Self {
        Self {
            version: 3,
            magic: *b"GGUF",
            metadata: Vec::new(),
            tensors: Vec::new(),
            alignment: 32,
            data_len: 0,
            declared_tensor_count: None,
            declared_metadata_count: None,
            trailing: Vec::new(),
        }
    }

    /// Append a metadata entry with a raw payload.
    pub fn meta(&mut self, key: &str, type_id: u32, payload: &[u8]) -> &mut Self {
        self.metadata
            .push((key.as_bytes().to_vec(), type_id, payload.to_vec()));
        self
    }

    /// Append a metadata entry keyed by raw bytes (for invalid UTF-8 keys).
    pub fn meta_raw_key(&mut self, key: &[u8], type_id: u32, payload: &[u8]) -> &mut Self {
        self.metadata
            .push((key.to_vec(), type_id, payload.to_vec()));
        self
    }

    /// Append a tensor info.
    pub fn tensor(&mut self, name: &str, dims: &[u64], type_id: u32, offset: u64) -> &mut Self {
        self.tensors
            .push((name.to_owned(), dims.to_vec(), type_id, offset));
        self
    }

    /// Set the data section length.
    pub fn data_len(&mut self, len: usize) -> &mut Self {
        self.data_len = len;
        self
    }

    /// Set the layout alignment.
    pub fn alignment(&mut self, alignment: u32) -> &mut Self {
        self.alignment = alignment;
        self
    }

    /// Override the header tensor count.
    pub fn declared_tensor_count(&mut self, count: u64) -> &mut Self {
        self.declared_tensor_count = Some(count);
        self
    }

    /// Override the header metadata count.
    pub fn declared_metadata_count(&mut self, count: u64) -> &mut Self {
        self.declared_metadata_count = Some(count);
        self
    }

    /// Append trailing bytes.
    pub fn trailing(&mut self, bytes: &[u8]) -> &mut Self {
        self.trailing.extend_from_slice(bytes);
        self
    }

    /// Assemble the file.
    #[must_use]
    pub fn build(&self) -> Vec<u8> {
        let mut writer = Writer::new();
        writer
            .raw(&self.magic)
            .u32(self.version)
            .u64(
                self.declared_tensor_count
                    .unwrap_or(self.tensors.len() as u64),
            )
            .u64(
                self.declared_metadata_count
                    .unwrap_or(self.metadata.len() as u64),
            );
        for (key, type_id, payload) in &self.metadata {
            writer
                .u64(key.len() as u64)
                .raw(key)
                .u32(*type_id)
                .raw(payload);
        }
        for (name, dims, type_id, offset) in &self.tensors {
            tensor_info(&mut writer, name, dims, *type_id, *offset);
        }
        if self.alignment != 0 {
            writer.pad_to_alignment(self.alignment as usize);
        }
        writer.zeros(self.data_len);
        writer.raw(&self.trailing);
        writer.into_bytes()
    }
}

/// Build a one-tensor file: version 3, no metadata, one `F32` tensor with the
/// given dimensions and data length, data starting at the default alignment.
#[must_use]
pub fn single_tensor_gguf(name: &str, dims: &[u64], data_len: usize) -> Vec<u8> {
    let mut gguf = RawGguf::new();
    gguf.tensor(name, dims, 0, 0).data_len(data_len);
    gguf.build()
}
